public boolean canArrange(int[] arr, int k) {
    int n = arr.length / 2;
    Map<Integer, Integer> map = new HashMap<>();
    for (int i = 0; i < n; i++) {
        int sum = arr[i] + arr[n + i];
        int mod = sum % k;
        if (mod == 0) {
            continue;
        }
        int complement = k - mod;
        if (map.containsKey(complement) && map.get(complement) > 0) {
            map.put(complement, map.get(complement) - 1);
            map.put(mod, map.getOrDefault(mod, 0) + 1);
        } else {
            map.put(mod, map.getOrDefault(mod, 0) + 1);
        }
    }
    return map.values().stream().allMatch(c -> c == 0);
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distances = new int[n];
    Arrays.fill(distances, Integer.MAX_VALUE);
    distances[0] = 0;

    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (distances[u] != Integer.MAX_VALUE) {
                distances[v] = Math.min(distances[v], distances[u] + 1);
            }
        }
    }

    int time = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            time += distances[i];
        }
    }

    return time;
}

